import pandas as pd

def find_cities_in_state(cities: pd.DataFrame) -> pd.DataFrame:
    def process_group(g):
        sorted_cities = sorted(g['city'])
        state = g['state'].iloc[0]
        match_count = sum(1 for c in sorted_cities if c[0].upper() == state[0].upper())
        return pd.Series({
            'cities': ', '.join(sorted_cities),
            'city_count': len(sorted_cities),
            'matching_letter_count': match_count
        })

    res = cities.groupby('state', as_index=False).apply(process_group)
    res = res[(res['city_count'] >= 3) & (res['matching_letter_count'] > 0)]
    return res[['state', 'cities', 'matching_letter_count']].sort_values(
        by=['matching_letter_count', 'state'],
        ascending=[False, True]
    )
